//! Differential ratchet for `src/engine/battleScriptAiReveal.ts`.
//! Expected state after every operation is generated by executing the
//! canonical TypeScript helpers; regenerate with `node
//! --experimental-strip-types core-rs/tools/gen-battle-script-ai-reveal-vectors.mjs`.

use factory_core::battle_script_ai_reveal::{
    record_battle_script_ability_reveal, record_battle_script_item_effect_reveal,
    BattleScriptAiRevealBattler, BattleScriptAiRevealRules, BATTLE_SCRIPT_AI_REVEAL_BATTLERS,
    BATTLE_SCRIPT_AI_REVEAL_BATTLER_COUNT,
};
use factory_core::battle_script_ai_reveal_vectors_gen::{
    BattleScriptAiRevealVectorCase, BattleScriptAiRevealVectorOperation,
    BattleScriptAiRevealVectorState, BATTLE_SCRIPT_AI_REVEAL_BATTLER_DOMAIN,
    BATTLE_SCRIPT_AI_REVEAL_BRANCH_CENSUS, BATTLE_SCRIPT_AI_REVEAL_CASES,
    BATTLE_SCRIPT_AI_REVEAL_CATEGORY_CENSUS, BATTLE_SCRIPT_AI_REVEAL_DOMAIN_CENSUS,
    BATTLE_SCRIPT_AI_REVEAL_OBSERVED_VALUE_DOMAIN, BATTLE_SCRIPT_AI_REVEAL_OPERATION_DOMAIN,
    BATTLE_SCRIPT_AI_REVEAL_VECTOR_CORPUS_SHA256,
};

fn battler(value: u8) -> BattleScriptAiRevealBattler {
    BattleScriptAiRevealBattler::try_from(value)
        .unwrap_or_else(|error| panic!("generator emitted invalid battler {value}: {error}"))
}

fn rules(value: BattleScriptAiRevealVectorState) -> BattleScriptAiRevealRules {
    BattleScriptAiRevealRules {
        ai_observed_ability_ids: value.ai_observed_ability_ids,
        ai_observed_item_effects: value.ai_observed_item_effects,
    }
}

fn vector_state(value: BattleScriptAiRevealRules) -> BattleScriptAiRevealVectorState {
    BattleScriptAiRevealVectorState {
        ai_observed_ability_ids: value.ai_observed_ability_ids,
        ai_observed_item_effects: value.ai_observed_item_effects,
    }
}

fn non_target_cells_are_distinct(cells: [u8; 4], target: usize) -> bool {
    let mut values = [0; BATTLE_SCRIPT_AI_REVEAL_BATTLER_COUNT - 1];
    let mut write_index = 0;
    for (index, value) in cells.into_iter().enumerate() {
        if index != target {
            values[write_index] = value;
            write_index += 1;
        }
    }
    values[0] != values[1] && values[0] != values[2] && values[1] != values[2]
}

#[test]
fn complete_outputs_preserve_siblings_non_targets_and_inputs() {
    assert_eq!(BATTLE_SCRIPT_AI_REVEAL_CASES.len(), 20);
    for (case_index, case) in BATTLE_SCRIPT_AI_REVEAL_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptAiRevealVectorCase) {
    let original_input = rules(case.initial);
    let mut current = original_input;
    for (step_index, step) in case.steps.iter().enumerate() {
        let before = current;
        let battler = battler(step.battler);
        let target_index = battler.index();
        let selected_before = match step.operation {
            BattleScriptAiRevealVectorOperation::Ability => before.ai_observed_ability_ids,
            BattleScriptAiRevealVectorOperation::ItemEffect => before.ai_observed_item_effects,
        };
        assert!(
            non_target_cells_are_distinct(selected_before, target_index),
            "case {case_index} {} step {step_index}: generator must keep non-target cells distinct",
            case.label,
        );

        let next = match step.operation {
            BattleScriptAiRevealVectorOperation::Ability => {
                record_battle_script_ability_reveal(&current, battler, step.value)
            }
            BattleScriptAiRevealVectorOperation::ItemEffect => {
                record_battle_script_item_effect_reveal(&current, battler, step.value)
            }
        };

        assert_eq!(
            current, before,
            "case {case_index} {} step {step_index}: input mutated",
            case.label,
        );
        assert_eq!(
            vector_state(next),
            step.expected,
            "case {case_index} {} step {step_index}: complete output",
            case.label,
        );
        assert_eq!(
            next == before,
            step.returned_input,
            "case {case_index} {} step {step_index}: equality fast path",
            case.label,
        );

        match step.operation {
            BattleScriptAiRevealVectorOperation::Ability => {
                assert_eq!(
                    next.ai_observed_item_effects, before.ai_observed_item_effects,
                    "case {case_index} {} step {step_index}: ability reveal changed item sibling",
                    case.label,
                );
                for index in 0..BATTLE_SCRIPT_AI_REVEAL_BATTLER_COUNT {
                    if index != target_index {
                        assert_eq!(
                            next.ai_observed_ability_ids[index], before.ai_observed_ability_ids[index],
                            "case {case_index} {} step {step_index}: ability reveal changed non-target {index}",
                            case.label,
                        );
                    }
                }
            }
            BattleScriptAiRevealVectorOperation::ItemEffect => {
                assert_eq!(
                    next.ai_observed_ability_ids, before.ai_observed_ability_ids,
                    "case {case_index} {} step {step_index}: item reveal changed ability sibling",
                    case.label,
                );
                for index in 0..BATTLE_SCRIPT_AI_REVEAL_BATTLER_COUNT {
                    if index != target_index {
                        assert_eq!(
                            next.ai_observed_item_effects[index], before.ai_observed_item_effects[index],
                            "case {case_index} {} step {step_index}: item reveal changed non-target {index}",
                            case.label,
                        );
                    }
                }
            }
        }
        current = next;
    }
    assert_eq!(
        original_input,
        rules(case.initial),
        "case {case_index} {}: chained operations mutated initial input",
        case.label,
    );
}

#[test]
fn typed_battler_and_observation_domains_are_exactly_bounded() {
    assert_eq!(BATTLE_SCRIPT_AI_REVEAL_BATTLER_COUNT, 4);
    assert_eq!(BATTLE_SCRIPT_AI_REVEAL_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_AI_REVEAL_OBSERVED_VALUE_DOMAIN, [0, 255]);
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_BATTLERS.map(|battler| battler as u8),
        BATTLE_SCRIPT_AI_REVEAL_BATTLER_DOMAIN,
    );
    for value in BATTLE_SCRIPT_AI_REVEAL_BATTLER_DOMAIN {
        assert_eq!(
            BattleScriptAiRevealBattler::try_from(value).unwrap() as u8,
            value
        );
    }
    assert!(BattleScriptAiRevealBattler::try_from(4).is_err());
    assert!(BattleScriptAiRevealBattler::try_from(u8::MAX).is_err());
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_OPERATION_DOMAIN,
        ["ability", "item-effect"],
    );
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("observed-u8-values", 256),
            ("operations", 2),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_CATEGORY_CENSUS,
        [
            ("ability-changed", 4),
            ("ability-unchanged", 5),
            ("chain-boundary-round-trip", 1),
            ("chain-interleaved", 1),
            ("item-effect-changed", 4),
            ("item-effect-unchanged", 5),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_BRANCH_CENSUS,
        [
            ("ability-replace-cell", 9),
            ("ability-return-input", 8),
            ("item-effect-replace-cell", 8),
            ("item-effect-return-input", 8),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_AI_REVEAL_VECTOR_CORPUS_SHA256,
        "8d7732702b8d372a71d60683471429a6285966deb6ee95e87302c44abe7e3652",
    );
}
